Aquí te presento un ejemplo de un programa en C++ que lee un archivo de texto línea por línea y cuenta el número de apariciones de una palabra específica en el archivo:

```cpp
#include <iostream>
#include <fstream>
#include <string>

int main() {
    std::string palabra; // palabra a buscar
    std::string linea;   // línea actual del archivo
    std::ifstream archivo; // flujo de entrada para el archivo
    int contador = 0;     // contador de apariciones de la palabra

    // solicitar la palabra a buscar
    std::cout << "Ingrese la palabra a buscar: ";
    std::getline(std::cin, palabra);

    // abrir el archivo para leer
    std::cout << "Ingrese el nombre del archivo: ";
    std::string nombreArchivo;
    std::getline(std::cin, nombreArchivo);
    archivo.open(nombreArchivo);

    // verificar si se abrió el archivo correctamente
    if (!archivo.is_open()) {
        std::cerr << "Error al abrir el archivo." << std::endl;
        return 1;
    }

    // leer línea por línea y contar apariciones de la palabra
    while (getline(archivo, linea)) {
        std::size_t posicion = 0;
        while ((posicion = linea.find(palabra, posicion)) != std::string::npos) {
            contador++;
            posicion += palabra.length(); // avanzar a la siguiente aparición
        }
    }

    // cerrar el archivo
    archivo.close();

    // mostrar el resultado
    std::cout << "La palabra \"" << palabra << "\" aparece " << contador << " veces en el archivo." << std::endl;

    return 0;
}
```

Este programa realiza los siguientes pasos:

